#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; cin >> t;
    while(t--){
        int n; cin >> n;
        vector<vector<long long>> d(n, vector<long long>(n));
        for(auto &row:d) for(auto &v:row) cin >> v;
        vector<int> order(n); for(auto &v:order) cin >> v;
        vector<bool> active(n,false); long long total=0;
        for(int step=n-1;step>=0;--step){
            int k=order[step]; active[k]=true;
            for(int i=0;i<n;++i) for(int j=0;j<n;++j) d[i][j]=min(d[i][j],d[i][k]+d[k][j]);
            for(int i=0;i<n;++i) if(active[i]) for(int j=0;j<n;++j) if(active[j]) total+=d[i][j];
        }
        cout << total << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int t;
    scanf("%d",&t);
    while(t--){
        int n;
        scanf("%d",&n);
        vector<vector<ll>> d(n, vector<ll>(n));
        for(int i=0;i<n;i++) for(int j=0;j<n;j++) scanf("%lld",&d[i][j]);
        for(int k=0;k<n;k++)
            for(int i=0;i<n;i++)
                for(int j=0;j<n;j++)
                    if(d[i][k]+d[k][j] < d[i][j]) d[i][j]=d[i][k]+d[k][j];
        vector<int> order(n);
        for(int i=0;i<n;i++) scanf("%d",&order[i]);
        vector<bool> active(n,true);
        ll total=0;
        for(int i=0;i<n;i++) for(int j=0;j<n;j++) if(i!=j) total += d[i][j];
        ll grandTotal=0;
        for(int step=0; step<n; step++){
            int x=order[step];
            grandTotal += total;
            for(int y=0;y<n;y++){
                if(y!=x && active[y]){
                    total -= d[x][y];
                    total -= d[y][x];
                }
            }
            active[x]=false;
        }
        printf("%lld\n", grandTotal);
    }
}

